"""Inspect source-bound generated-hash and task-order receipts, not generated bytes absent from artifact."""
import hashlib,re

def need(ok,message):
 if not ok:raise ValueError(message)
def h(b):return hashlib.sha256(b).hexdigest()
def verify(source,summary,logs):
 need(summary['wrapper_sha256']==h((source/'gradle/wrapper/gradle-wrapper.properties').read_bytes()),'wrapper source binding')
 need(summary['root_build_sha256']==h((source/'build.gradle').read_bytes()),'root build source binding')
 need(summary['excluded_task']==':Paintroid:bundleCorrespondingSource','unexpected exact-script exclusion')
 mirrors=[('Paintroid/src/main/res/values-b+ko+Kore+KR','values-b+ko+Kore+KR+anpaint'),('Paintroid/src/main/res/values-b+qaa+Zsye+XV','values-b+en+Zsye+XV+anpaint')]
 expected={};mutated={}
 for i,(folder,qualifier) in enumerate(mirrors,1):
  files=sorted((source/folder).glob('*.xml'));need(bool(files),'missing canonical mirror')
  for path in files:expected[qualifier+'/'+path.name]=h(path.read_bytes())
  mutated[i]=(qualifier+'/'+files[0].name,h(files[0].read_bytes()+b'\n<!-- isolated incremental resource probe -->\n'))
 probes={p['name']:p for p in summary['probes']};generator=':Paintroid:generateExactScriptResources';fallback=':Paintroid:generateSourceTextResources';debug=':Paintroid:mergeDebugResources';release=':Paintroid:mergeReleaseResources'
 mirror_cases={'02-clean-debug-release':[debug,release],'07-release-first-after-clean':[release]}
 for i in (1,2):mirror_cases[f'04-{i}-input-change-and-stale-output']=[debug];mirror_cases[f'05-{i}-restored-input-release']=[release]
 source_cases={'02-clean-debug-release':[debug,release],'05-source-change-and-stale-output':[debug],'05-source-companion-added':[debug],'05-source-companion-removed':[release],'07-release-first-after-clean':[release]}
 tasks={}
 for name,p in probes.items():
  tasks[name]=re.findall(r'^> Task (:[^\s]+)([^\n]*)$',logs[name],re.M)
  need([list(x) for x in tasks[name]]==p['tasks'],'recorded task list differs from log '+name)
 def before(name,gen,consumers,state=''):
  pairs=tasks[name];names=[x[0] for x in pairs];need(names.count(gen)==1,'generator occurrence '+name);i=names.index(gen)
  need(pairs[i][1].strip()==state,'generator outcome '+name)
  for c in consumers:need(names.count(c)==1 and names.index(c)>i,'generator order '+name)
 for name,consumers in mirror_cases.items():
  target=dict(expected)
  if name.startswith('04-'):
   key,value=mutated[int(name[3])];target[key]=value
  need(probes[name]['generated_sha256']==target,'source-bound generated mirror hashes '+name);before(name,generator,consumers)
 for gen in (generator,fallback):before('03-unchanged',gen,[],state='UP-TO-DATE')
 baseline=probes['02-clean-debug-release']['source_text_sha256'];need(set(baseline)=={'values/source_text.xml','values/source_text_contracts.xml'} and all(re.fullmatch('[0-9a-f]{64}',v) for v in baseline.values()),'source fallback hash inventory')
 for name,consumers in source_cases.items():
  hashes=probes[name]['source_text_sha256'];need(set(hashes)==set(baseline),'source fallback generated files '+name);before(name,fallback,consumers)
  if name=='05-source-companion-added':need(all(hashes[k]!=baseline[k] and re.fullmatch('[0-9a-f]{64}',hashes[k]) for k in baseline),'source companion must change both generated outputs')
  else:need(hashes==baseline,'restored/comment-only fallback output differs '+name)
 negative='06-reserved-app-variant-rejected';need('Reserved source-text name' in logs[negative] and 'source_namespace_probe.xml' in logs[negative],'expected reserved-namespace rejection reason');before(negative,fallback,[],state='FAILED')
 return {'mirrors_bound_to_source':len(expected),'source_fallback_output_hashes':baseline,'task_order_and_up_to_date_checked':True,'generated_bytes_present_in_artifact':False,'limit':'Generated mirror hashes independently derived from exact source; fallback bytes are not in artifact, so its source-bound producer semantic validation and restored-output hash equality are checked, not a separate byte readback.'}
